import { DragToMove, } from '@utils/index'

document.addEventListener('DOMContentLoaded', () => {
  new DragToMove({
    el: '.jackery-pif-float-button',
    placement: 'left', // 目标位置，'left' - 靠左，'right' - 靠右
    offset: { // 偏移量
      x: 20,
      y: '20%',
    },
    onClick: () => {
      const pifDialog = document.querySelector('.pif-dialog')
      pifDialog?.setAttribute('open', true)

      gaPushDataLayer('form_user_clicks', {
        module: "FloatingExpertForm",// 固定模块命名FloatingExpertForm
        button_name: "FloatFormEntry", // 固定文案
      });
    },
  })
})
